from pathlib import Path
import json,html
BASE=Path('expansion-src')
def svg(inner,label):return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 210" role="img" aria-label="'+label+'"><rect width="760" height="210" rx="12" fill="#f4f7f5"/><g font-family="system-ui,Microsoft YaHei,sans-serif" font-size="18" fill="#23453f">'+inner+'</g></svg>'
def concept(labels,desc):
 n=len(labels);w=690/n
 return svg(''.join(f'<rect x="{30+i*w:.0f}" y="42" width="{w-22:.0f}" height="76" rx="8" fill="'+['#dceee6','#e2eaf4','#f2e6cc'][i%3]+'"/><text x="'+str(round(42+i*w))+'" y="87">'+x+'</text>'+ (f'<path d="M{30+i*w+w-20:.0f} 80h18l-5-4m5 4l-5 4" stroke="#718c81" fill="none"/>' if i<n-1 else '')for i,x in enumerate(labels))+'<text x="34" y="168">'+desc+'</text>',desc)
S={
'g2':dict(id='s17x-g2-geochemical-anomaly',title='油气地球化学异常：从单点高值到联合背景偏离',methods=['opt'],lede='地表土壤气中的甲烷升高，为什么还不能直接解释为油气线索？先认识背景、组分和采样位置，再用背景样本学习多指标的正常关系。',sections=[
('先问采到了什么，再看数值有多高','''<p>地球化学勘察把采样位置与化学测量放到一起：在一组地表点位采集土壤气，测量甲烷 C1、乙烷 C2、丙烷 C3 等组分。点位是空间位置，组分是这个位置的观测；两者必须同时保留，才能判断高值是否形成可追查的区域。</p><p>甲烷可以有不同来源，土壤条件与生物活动也会改变近地表浓度。因此，本例的问题是“哪里偏离了当地背景”，下一步才是回查样品、现场条件与其他资料。横轴和纵轴以 km 表示；浓度统一以 ppm 表示，不能直接把不同量级的三个数相加。</p>'''+concept(['同深度采样','气体组分测量','带坐标点位表'],'一个样品 = 坐标 + 浓度 + 采样记录'), '采样与化验记录共同构成异常判断的输入。'),
('背景不是一个固定常数，而是一组联合关系','''<p>背景点也有波动。假如 C1 与 C2 随同一种背景因素一起上升，沿着这条关系变化未必异常；相反，一个绝对数值不算很高、却明显偏离通常比例的点也值得关注。统计背景需要在待查区域之外的独立标定点上建立。</p><p>本例从 260 个背景样本学习三个组分的均值和协方差，计算 Mahalanobis 距离。协方差同时描述各指标的尺度和共同变化方向，因此把“沿背景变化”和“横穿背景关系”分开处理。单指标基线只看 C1 高于背景均值几个标准差。</p>'''+svg('<path d="M65 160V30m0 130h610" stroke="#8a9c93" fill="none"/><ellipse cx="295" cy="110" rx="150" ry="25" transform="rotate(-14 295 110)" fill="#bad7ca" fill-opacity=".7"/><path d="M145 147l310-79" stroke="#318173" stroke-width="2"/><circle cx="380" cy="43" r="8" fill="#bd7147"/><text x="85" y="38">C2 / ppm</text><text x="566" y="192">C1 / ppm →</text><text x="452" y="48">偏离联合背景</text><text x="194" y="165">长轴方向：常见共同变化</text>','C1与C2的相关背景和偏离点'),'椭圆为解释协方差的概念示意；运行时点位图来自实际生成数组。'),
('把异常带回空间位置，决定哪里复核','''<p>距离超过阈值的点会在地图上显示，但单个异常点与成片异常不能等同看待。点击一个点，先读其 C1–C3 数值，再看联合距离与单指标得分是否一致。阈值提高会减少候选，也可能漏掉边缘点；调节甲烷背景波动，能观察只依赖 C1 的规则为何更不稳定。</p><p>演示使用具有固定空间异常区的教学数据，训练点与测试点独立生成。模型只读取三项浓度；地图坐标用于定位，异常区标记只在预测后计算召回、误报与 F1。图中“参考异常”勾选开关仅控制评价层显示。专业阅读：<a href="https://pubs.usgs.gov/wri/1994/4006/report.pdf" target="_blank" rel="noopener">USGS 近地表气体组分研究</a>。</p>''','专业判断应回到采样与来源核查。')],controls='<label>甲烷背景波动 / ppm<input id="organic" type="range" min="0.2" max="4" step="0.1" value="1.8"><output id="organic-v"></output></label><label>联合距离阈值<input id="threshold" type="range" min="1.5" max="6" step="0.1" value="3.3"><output id="threshold-v"></output></label>',chartTitle='点位空间分布与背景关系',hint='点击地图点位查看三个浓度与两种方法判断；地图范围 10 × 8 km。',engine='G2Core',steps=[('建立独立背景','260个无目标异常背景点，保留C1–C3浓度。','计算均值与协方差，甲烷背景波动与当前设置一致。','背景均值、协方差逆矩阵与单指标标准差。','标定点不能混入目标异常区；浓度必须采用同一单位。'),('计算联合距离','独立180个测试点，只向评分函数传浓度向量。','按协方差归一化三组分的偏离，同时计算C1标准分数。','每个点的联合距离和单指标得分。','地图位置与参考异常标记不进入评分函数。'),('阈值筛选并定位','当前联合阈值和固定C1>2标准差基线。','分别筛选候选，在同一地图叠加并允许点选。','候选点清单、原始组分与模型依据。','异常仅代表背景偏离，甲烷来源需要额外地质化学证据。'),('独立参考核对','两种方法已固定的预测与教学参考。','计算TP、FP、FN及F1、召回和误报率。','相同180点分母下的比较与可导出结果。','空预测集精确率显示不适用，不补成100%。')]),
's3':dict(id='s17x-s3-first-arrival',title='初至波自动拾取：把第一段有效能量定位到时间轴',methods=['ts'],lede='炮响之后，各检波器最早何时接收到有效波？从走时曲线与带噪波形理解初至，再比较能量触发和学习边界的方法。',sections=[
('初至是最早可辨认的到达，不是最大的波峰','''<p>地震采集时，震源激发的弹性波向地下和地表传播，检波器把运动记录为一条随时间变化的地震道。一个炮点对应许多条地震道，合起来称为炮集。初至时间是每条记录上最早能识别的有效到达时间，用于近地表速度分析与后续处理。</p><p>最大波峰通常出现在初至之后：有效波刚到达时振幅可能很小，随后能量才逐渐增强。图中的横轴是记录时间，纵轴是振幅；炮集图则把每一条地震道横向排开，时间向下增加。本例采样间隔为 2 ms，道间距为 15 m。</p>'''+svg('<path d="M60 145H700M60 145V35" stroke="#91a59b" fill="none"/><path d="M65 145h170l8-4 8 7 8-7 8 6 10-15 10 28 10-45 10 59 10-63 10 55 10-44 10 28 10-13 10 8 10-4h240" stroke="#2a7e75" fill="none" stroke-width="3"/><path d="M235 36v130" stroke="#bc764d" stroke-dasharray="6 4"/><text x="155" y="30">初至：有效波刚开始</text><text x="420" y="72">较强波峰在后面</text><text x="557" y="187">时间 / ms →</text>','初至位置与较强波峰不同'),'振幅增强是过程，拾取要定位过程起点。'),
('噪声触发与弱信号漏拾，是两种不同错误','''<p>STA/LTA 用短时窗口与较长背景窗口的平均能量比判断波是否到达。短窗突然变强会触发，因此一个孤立脉冲也可能被误拾；弱道虽然已经有有效波，能量比却可能迟迟不够高。</p><p>学习路线把前后窗口能量比、短窗能量、相邻采样变化和邻道能量一起交给逻辑回归。训练来自 7 个独立炮集，模型学习波前与波后窗口的差异，再在新炮集寻找连续三个采样点超过阈值的位置。邻道特征提供观测支持，不能直接复制参考走时。</p>'''+concept(['原始带噪炮集','局部能量与邻道','连续触发位置'],'局部输入 → 学习支持度 → 初至时间（2 ms/采样）'),'STA/LTA 与学习模型对同一炮集分别拾取，真实计算误差。'),
('评价拾取时间，也保留漏拾和人工修正','''<p>平均绝对误差 MAE 衡量已拾取道的时间偏差；±10 ms 命中率则以全部 18 道作分母，漏拾不能消失在分母里。参考初至用金色虚线叠加，学习拾取与 STA/LTA 各用一种颜色；点击炮集可切换正在放大的单道。</p><p>演示中的炮集为教学合成波形，参考到达由生成过程保留并与预测函数分开。调高噪声或降低每六道中一条弱道的振幅，观察方法何时失效。人工修正只形成复核记录，保留原模型成绩。阅读：<a href="https://wiki.seg.org/wiki/First_breaks" target="_blank" rel="noopener">SEG First breaks</a>、<a href="https://doi.org/10.1002/nsg.12316" target="_blank" rel="noopener">初至拾取研究</a>。</p>''','误差图回答“差了多少”，波形回答“为什么这样拾取”。')],controls='<label>噪声幅度<input id="noise" type="range" min="0.02" max="0.5" step="0.02" value="0.14"><output id="noise-v"></output></label><label>弱道振幅比例<input id="weak" type="range" min="0.15" max="1" step="0.05" value="0.55"><output id="weak-v"></output></label><label>学习触发阈值<input id="threshold" type="range" min="0.3" max="0.85" step="0.05" value="0.55"><output id="threshold-v"></output></label>',chartTitle='炮集拾取与单道证据',hint='点击左侧炮集选中一条地震道，右图同步显示波形与三种时间位置。',engine='S3Core',steps=[('以炮集为单位划分','7个独立训练炮集与独立测试炮集。','从波前、波后窗口采样，保留炮集来源分组。','训练窗口与独立18道测试观测。','不能把同一炮集中相邻窗口随机分到训练与测试。'),('提取波前变化','每道当前时刻附近的振幅与相邻道。','计算前后能量比、短窗能量、变化量和邻道能量。','四维局部观测特征。','前后窗口意味着离线拾取；不宣称是无延迟实时预警。'),('拟合与实际拾取','仅训练炮集的窗口特征和训练参考。','180轮梯度下降拟合逻辑回归，在新炮集找连续触发。','每道支持度曲线、首个连续触发位置与损失记录。','阈值由用户设置，不在测试参考上自动找最优值。'),('对比并复核','固定STA/LTA触发、学习拾取与独立参考。','计算MAE、全部道命中率及漏拾，点选弱道复查。','波形、误差表、人工修正记录与JSON。','人工修正与原始模型输出分别保存。')]),
's5':dict(id='s17x-s5-seismic-denoise',title='地震资料噪声压制：降低干扰，也检查反射是否保真',methods=['cv'],lede='一条更平滑的地震道不一定更正确。观察反射波的峰谷、邻道连续性和残差，理解学习去噪为什么要同时检查降噪与信号保留。',sections=[
('振幅记录由反射信号和干扰共同组成','''<p>地下介质的弹性性质发生变化时，会产生反射波。检波器记录的是随时间变化的振幅，其中还混有环境、采集或其他传播成分造成的干扰。处理的目标是让有用反射更容易识别，同时保留峰谷位置和波形形态。</p><p>随机噪声在相邻采样点间变化快；相干干扰具有一定规律，可能跨道延续；脉冲噪声则表现为少数异常尖峰。三类噪声对同一种方法提出不同难题。演示可切换噪声类型，输入的观测都是真正相加得到的数组。</p>'''+svg('<path d="M42 72h675M42 142h675" stroke="#b5c5be"/><path d="M45 72h160q20-60 40 0t40 0h110q20-50 40 0t40 0h230" stroke="#2f7c71" fill="none" stroke-width="3"/><path d="M45 142l15-13 15 21 15-11 15 15 15-19 15 11 15-7 15 9 15-12 15 6 15-10 15 15 15-11 15 7 15-5 15 12 15-16 15 6 15 7 15-13 15 13 15-7 15 5 15-9 15 13 15-10 15 8 15-10 15 14 15-6 15 5 15-11 15 9 15-5 15 11 15-8 15 4 15-10 15 8 15-4 15 7" stroke="#b97a50" fill="none" stroke-width="2"/><text x="45" y="32">反射信号：波峰与波谷携带结构信息</text><text x="45" y="193">干扰：可能随机、相干或含有尖峰；不能只追求平滑</text>','反射信号与噪声的不同形态'),'概念波形用于解释组成；可运行示范显示独立炮集实际数组。'),
('让模型学习“邻域观测如何还原中心采样”','''<p>滑动平均把相邻五个采样点平均，能减弱随机起伏，却也会压低窄波峰。学习去噪则使用训练炮集中“带噪邻域—干净中心采样”的成对样本，拟合合适的线性组合。本例采用岭回归，特征是同道前后两点、当前点和左右邻道当前点，共七个振幅，加一个截距。</p><p>正则项约束权重大小，避免过度追随训练噪声。模型在 6 个独立炮集上真实求解线性方程，预测新炮集时只读取带噪数组。干净参考只在训练标定和预测后的独立评价使用；测试参考不进入预测函数。</p>'''+concept(['带噪7点邻域','岭回归学习权重','中心采样估计'],'训练用成对样本；测试仅输入带噪观测'),'可展开权重表，查看模型到底平均了哪些位置。'),
('同时看结果、差值和信噪比','''<p>均方根误差 RMSE 比较全部 12 道 × 160 点与干净参考的偏差；信噪比 SNR 把参考信号能量与误差能量相比，单位 dB。指标由当前数组实际计算，分母为全部 1920 个采样点。</p><p>差值“原始−处理”表示被移除的部分：若差值中出现清晰的反射波形，可能连有效信号也删掉了。模型训练只包含随机噪声，切换相干或脉冲噪声可以观察分布变化导致的失效。教学波形按局部反射脉冲生成。方法阅读：<a href="https://scikit-learn.org/stable/modules/generated/sklearn.linear_model.Ridge.html" target="_blank" rel="noopener">岭回归目标与正则化</a>。专业概念：<a href="https://glossary.slb.com/en/terms/s/seismic_processing" target="_blank" rel="noopener">SLB Seismic processing</a>。</p>''','优先解释峰谷与残差，再看单个汇总分数。')],controls='<label>噪声幅度<input id="noise" type="range" min="0.04" max="0.7" step="0.02" value="0.24"><output id="noise-v"></output></label><label>噪声类型<select id="type"><option value="random">随机噪声（训练分布）</option><option value="coherent">相干干扰（分布外）</option><option value="spikes">脉冲尖峰（分布外）</option></select></label>',chartTitle='带噪炮集与处理后波形',hint='点击炮集选择地震道。右侧对比原始、学习去噪、滑动平均和干净参考；差值图检查被移除的成分。',engine='S5Core',steps=[('成对炮集标定','6个独立炮集，各有带噪观测和训练干净目标。','只在训练炮集提取邻域—中心成对样本。','5616个训练采样窗口与独立测试炮集。','独立炮集分组；相邻窗口不能跨训练测试混用。'),('建立邻域回归','同道±2点和左右邻道当前点，加截距。','构造正规方程并加入0.4的L2正则项。','8个拟合系数，可逐项查看。','权重依据训练信号与噪声分布，不能假定适合所有干扰。'),('预测并运行基线','当前带噪炮集，仅有观测振幅。','岭回归逐点估计中心值，同时计算5点滑动平均。','学习结果、平均结果与各自移除差值。','两种方法使用相同输入，测试干净参考不进入推理。'),('检查保真与失效','两种结果与独立测试干净参考。','计算RMSE、SNR与SNR改善，检查选中道的波峰和残差。','全1920点对比、权重表与可导出数组。','分布外噪声可能降低效果；保留这种结果供教学解释。')])}
css='''*{box-sizing:border-box}body{margin:0;background:#f4f6f3;color:#253b38;font:18px/1.85 system-ui,"Microsoft YaHei",sans-serif}header,main{max-width:1120px;margin:auto;padding:24px}header{padding-bottom:10px}h1{font-size:30px;line-height:1.5;margin:10px 0}h2{font-size:25px}h3{font-size:21px}p{margin:12px 0 18px}nav{display:flex;gap:8px;position:sticky;top:0;background:#f4f6f3f5;padding:12px 0;z-index:3}button,select,input{font:inherit}button{border:1px solid #b7c8bf;border-radius:9px;padding:9px 18px;background:white;color:#254c42;cursor:pointer}button.active,.primary{background:#2c7565;color:white}.pane>article,.card,.step{background:white;border:1px solid #dce5de;border-radius:12px;padding:25px;margin:18px 0}figure{margin:18px 0}figure svg{width:100%;max-height:210px;display:block}figcaption,.note{font-size:15px;color:#62766d}a{color:#236d68}label{display:flex;flex-direction:column;gap:6px}input[type=range]{width:100%}.controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:20px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}#status{padding:12px;background:#e8f0e9;border-radius:8px}#status[data-state=stale]{background:#fff0d4}.charts{display:grid;grid-template-columns:1fr 1fr;gap:20px}canvas{width:100%;height:330px;background:#fbfcfa;border:1px solid #dfe8e1;border-radius:8px;cursor:crosshair}.wide{grid-column:1/-1;height:210px}table{border-collapse:collapse;width:100%;font-size:16px}th,td{padding:10px;border-bottom:1px solid #dfe5df;text-align:left}.scroll{overflow:auto}.metric{display:flex;gap:18px;flex-wrap:wrap}.metric strong{font-size:24px;color:#23725f}.metric>div{padding:12px 16px;background:#edf4ee;border-radius:8px}output{font-size:15px;color:#426c5d}.legend{font-size:15px;color:#526a60}[hidden]{display:none!important}#detail{background:#f3f7f2;padding:16px;border-radius:8px}.intro{max-width:940px}.step small{color:#6b7d73}dl{display:grid;grid-template-columns:100px 1fr;gap:8px}dt{font-weight:700}dd{margin:0}.source-badge{font-size:14px;letter-spacing:.06em;color:#3e7966}@media(max-width:700px){header,main{padding:16px}h1{font-size:25px}.charts{grid-template-columns:1fr}canvas{height:300px}.pane>article,.card,.step{padding:18px}nav{gap:5px}nav button{padding:8px 12px;font-size:16px}dl{grid-template-columns:1fr}dd{margin-bottom:10px}}'''
for scene,d in S.items():
 path=BASE/scene
 sections=[dict(no=i+1,en=['CONTEXT','METHOD','READING'][i],title=t,html=p+(f'<p class="note">{cap}</p>' if cap else ''))for i,(t,p,cap)in enumerate(d['sections'])]
